<?php cms_view('public/hero',compact('page'));?><main><section class="section-padding product-catalog"><div class="container"><div class="catalog-layout"><aside class="catalog-sidebar"><div class="catalog-sidebar-section"><div class="catalog-sidebar-title"><?=text('brands')?></div><a class="catalog-category-link <?=empty(request()->query()['brand'])?'active':''?>" href="<?=e(cms_url('/brochures/'))?>"><?=text('all_brands')?></a><?php foreach($brands as $brand):?><a class="catalog-category-link <?=(int)(request()->query()['brand']??0)===(int)$brand['id']?'active':''?>" href="<?=e(cms_url('/brochures/?brand='.$brand['id']))?>"><?=e($brand['title'])?></a><?php endforeach?></div></aside><div class="catalog-main"><nav class="sub-category-nav"><a class="active" href="<?=e(cms_url('/brochures/'))?>"><?=text('brochures')?></a><a class="catalog-brochure-link" href="<?=e(cms_url('/products/'.(!empty(request()->query()['brand'])?'?brand='.(int)request()->query()['brand']:'')))?>"><i class="fa-solid fa-box"></i> <?=text('view_products')?></a></nav><div class="catalog-heading-row"><h2><?=text('brochures')?></h2><form class="catalog-search-form"><?php if(!empty(request()->query()['brand'])):?><input type="hidden" name="brand" value="<?=(int)request()->query()['brand']?>"><?php endif?><input type="search" name="q" value="<?=e($q)?>" placeholder="<?=text('search_brochures')?>" aria-label="<?=text('search_brochures')?>"><select name="category" class="form-select" aria-label="<?=text('category')?>"><option value=""><?=text('all_categories')?></option><?php foreach($categories as $category):?><option value="<?=$category['id']?>" <?=(int)(request()->query()['category']??0)===(int)$category['id']?'selected':''?>><?=e($category['title'])?></option><?php endforeach?></select><button><?=text('search')?></button></form></div><div class="catalog-products-grid"><?php foreach($brochures as $brochure):?><a class="catalog-product-card brochure-card" href="<?=e(cms_url('/brochures/'.$brochure['id'].'/pdf/'))?>" target="_blank" rel="noopener"><?php if($brochure['image_id']):?><div class="catalog-product-media"><?=media_img($brochure['image_id'],$brochure['title'])?></div><?php else:?><div class="catalog-product-media catalog-product-placeholder"><i class="fa-regular fa-file-pdf"></i></div><?php endif?><h3><?=e($brochure['title'])?></h3><p><?=e($brochure['description'])?></p><span class="brochure-action"><?=text('view_pdf')?> <i class="fa-solid fa-arrow-up-right-from-square"></i></span></a><?php endforeach?><?php if(!$brochures):?><div class="catalog-empty"><i class="fa-regular fa-file-pdf"></i><h3><?=text('no_brochures')?></h3><p><?=text('no_brochures_intro')?></p></div><?php endif?></div><?php cms_view('public/pagination',compact('total','number','perPage'));?></div></div></div></section><?php if($page['body']):?><section class="section-padding"><div class="container rich-text"><?=rich($page['body'])?></div></section><?php endif?><?php foreach($sections as $section)cms_view('public/section',compact('section'));?></main>
